import {QuantumLab} from './lab.js';
import {stages,sources,modelNote,modelDetails,createExperiment,runComparison} from './science.js';

const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
const pct=n=>(n*100).toFixed(1)+'%';
const shortTitles=['制备信号','保存参考','发射探测','接收噪声','匹配校准','联合测量','积累证据','判决验证'];
let saved={};try{saved=JSON.parse(localStorage.getItem('quantum-echo-progress')||'{}');}catch{}
const state={mode:'guide',stage:Number.isInteger(saved.stage)&&saved.stage>=0&&saved.stage<8?saved.stage:0,completed:new Set((saved.completed||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<8)),noise:.6,retention:.95,alignment:1,offset:-32,running:false,paused:false,targetPresent:true,experiment:null,guideDecision:null,comparison:null,challenge:null,quizAnswers:new Set()};
const lab=new QuantumLab($('#lab'));
let statusTimer,modalReturnFocus;
function persist(){try{localStorage.setItem('quantum-echo-progress',JSON.stringify({stage:state.stage,completed:[...state.completed]}));}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(statusTimer);statusTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function markDone(index=state.stage){state.completed.add(index);persist();renderTrack();}
function config(){return {noise:state.noise,retention:state.retention,alignment:state.alignment,mode:'quantum'};}
function newExperiment(target=true){state.experiment=createExperiment({...config(),targetPresent:target,seed:seed()});return state.experiment;}
function syncLab(){const ch=state.challenge;const hidden=state.mode==='challenge'&&!ch?.revealed||state.mode==='guide'&&state.stage===7&&!state.guideDecision;lab.setState({stage:state.mode==='guide'?state.stage:6,running:state.running&&!state.paused,noise:state.mode==='guide'&&state.stage<3?.08:state.noise,retention:state.retention,alignment:state.stage===4&&state.mode==='guide'?Math.exp(-Math.pow(state.offset/22,2)):state.alignment,targetVisible:!hidden,targetPresent:state.mode==='challenge'?ch?.target??true:state.targetPresent,samples:state.experiment?.getSnapshot().samples||0});$('#bench-live').textContent=state.paused?'动画已暂停':state.running?'实验运行中':'设备待机';$('#motion-toggle').textContent=state.paused?'▷':'Ⅱ';$('#motion-toggle').setAttribute('aria-label',state.paused?'继续装置动画':'暂停装置动画');$('#bench-note').textContent=hidden?'目标真值已隐藏 · 请根据测量证据判断':'点击设备，也可以探索它的作用';}
function pulse(){state.running=true;if(!state.paused)lab.pulse();syncLab();}
function renderTrack(){const current=state.stage;$('#journey-progress').textContent=`已探索 ${state.completed.size} / 8`;$('#step-track').innerHTML=stages.map((s,i)=>`<button class="step-button ${i===current&&state.mode==='guide'?'active':''} ${state.completed.has(i)?'complete':''}" data-stage="${i}" ${i===current&&state.mode==='guide'?'aria-current="step"':''} aria-label="第${i+1}步：${s.title}${state.completed.has(i)?'，已探索':''}"><span class="step-number">${state.completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${shortTitles[i]}</span></button>`).join('');}
function range(id,label,value,left,right,display){return `<div class="range-group"><label class="range-label" for="${id}"><span>${label}</span><output id="${id}-value">${display||value+'%'}</output></label><input id="${id}" type="range" min="0" max="100" value="${value}"/><div class="range-ends"><span>${left}</span><span>${right}</span></div></div>`;}
function evidence(snapshot){const s=snapshot||{samples:0,llr:0,readings:[]};const pos=50+45*Math.tanh(s.llr/5);const values=s.readings.slice(-40);const pts=values.map((v,i)=>`${5+i*250/Math.max(1,values.length-1)},${23-Math.max(-3,Math.min(3,v))*6}`).join(' ');return `<div class="readout-row"><div class="readout"><span>已采集样本</span><strong>${s.samples}<small> 次</small></strong></div><div class="readout"><span>累计证据</span><strong>${s.llr>0?'+':''}${s.llr.toFixed(2)}</strong></div></div><div class="evidence-labels"><span>偏向无目标</span><span>偏向有目标</span></div><div class="evidence-track"><span class="evidence-marker" style="left:${pos}%"></span></div><svg class="sparkline" viewBox="0 0 260 46" preserveAspectRatio="none" role="img" aria-label="最近${values.length}次随机教学读数"><path d="M0 23H260" stroke="#dae3ce" stroke-dasharray="3 3"/>${values.length?`<polyline fill="none" stroke="#829f60" stroke-width="1.4" points="${pts}"/>`:''}</svg><p class="sampling-note">证据值是对数似然比，并非目标存在概率。曲线显示随机教学读数。</p>`;}
function comparisonHTML(result){if(!result)return '';return `<div class="comparison-chart">${[['quantum','量子方案',''],['classical','经典方案','classic']].map(([key,label,cl])=>`<div class="comparison-row ${cl}"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${result[key].accuracy*100}%"></div></div><strong>${pct(result[key].accuracy)}</strong></div>`).join('')}</div><table class="comparison-table"><caption style="text-align:left;font-size:10px;padding-bottom:5px">本轮模拟的判决正确率与错误次数</caption><thead><tr><th>教学方案</th><th>误报 / 无目标</th><th>漏检 / 有目标</th></tr></thead><tbody>${[['quantum','量子'],['classical','经典']].map(([k,l])=>`<tr><td>${l}</td><td>${result[k].falseAlarms} / ${result[k].nAbsent}</td><td>${result[k].misses} / ${result[k].nPresent}</td></tr>`).join('')}</tbody></table><p class="compare-note">每种方案 400 次试验，每次 24 个样本；相同目标序列、噪声与采样预算。上述比例来自本页教学模型。</p>`;}
function guideControls(i){switch(i){case 0:return '<div class="signal-preview"><span class="signal-orb"></span><span class="correlation-line"></span><span class="signal-orb purple"></span></div><div class="signal-caption"><span>发出的探测</span><span>保留的参考</span></div>';case 1:return range('retention','参考保留程度',Math.round(state.retention*100),'大量损失','充分保存');case 2:return `<div class="switch-row" aria-label="教学目标状态"><button data-target="true" class="${state.targetPresent?'selected':''}" aria-pressed="${state.targetPresent}">放入目标</button><button data-target="false" class="${!state.targetPresent?'selected':''}" aria-pressed="${!state.targetPresent}">移走目标</button></div><p class="sampling-note">教学剖视模式 · 此处可以观察真实目标状态。</p>`;case 3:return range('noise','背景噪声强度',Math.round(state.noise*100),'较弱','较强');case 4:return `<div class="range-group"><label class="range-label" for="alignment"><span>接收时间窗</span><output id="alignment-value">${Math.abs(state.offset)<=5?'已对齐':state.offset<0?'偏早':'偏晚'}</output></label><input id="alignment" type="range" min="-50" max="50" value="${state.offset}"/><div class="range-ends"><span>提前</span><span>同步</span><span>延后</span></div></div><p class="sampling-note">使用已知目标校准。把接收窗口移到同步位置。</p>`;case 5:return state.experiment?evidence(state.experiment.getSnapshot()):'<div class="mini-flow"><b>含噪回波</b><span>＋</span><b>保留参考</b><span>→</span><div class="receiver-icon">∿</div></div>';case 6:return evidence(state.experiment?.getSnapshot());case 7:return evidence(state.experiment?.getSnapshot())+(state.guideDecision?`<div class="result-message ${state.guideDecision.correct?'':'incorrect'}">${state.guideDecision.correct?'判断正确':'这次发生了'+(state.guideDecision.guess?'误报':'漏检')}。实际${state.targetPresent?'存在':'不存在'}目标。单次结果之外，还需要多次试验评价方法。</div>${comparisonHTML(state.comparison)}`:`<div class="decision-buttons"><button data-guess="true">◎ 有目标</button><button data-guess="false">○ 无目标</button></div>`);default:return '';}}
function renderGuide(){const s=stages[state.stage],done=state.completed.has(state.stage);let instruction=s.instruction;if(state.stage===5)instruction='让回波与保留参考进入联合接收器，获得第一份随机测量读数。';if(state.stage===6)instruction='每次增加 8 个样本。至少采集 24 次，观察证据怎样波动，再继续。';if(state.stage===7)instruction='目标已重新随机放置。观察这组独立的 24 次读数，选择有目标或无目标。';const canNext=state.stage===7?!!state.guideDecision:done;$('#control-panel').innerHTML=`<div class="panel-enter"><div class="chapter-kicker"><span>${s.kicker.split(' / ')[1]}</span><span class="chapter-number">${String(state.stage+1).padStart(2,'0')} / 08</span></div><h2 class="chapter-title">${s.title}</h2><p class="chapter-description">${s.description}</p><div class="task-card"><div class="task-label">↳ 现在试试看</div><p>${instruction}</p></div><div class="control-area">${guideControls(state.stage)}</div></div><div class="panel-actions">${state.stage<7?`<button class="primary-button" id="main-action"><span>${state.stage===6?'再采集 8 次':s.actionLabel}</span><span class="arrow">↗</span></button>`:''}<p class="action-status" id="action-status" role="status" aria-live="polite">${done&&state.stage<7?'✓ 已完成这一环节，可以继续探索。':''}</p><div class="panel-next"><span>${state.stage===7?'从理解原理，到独立探测':'每一步，理解一件事'}</span><button class="next-button" id="next-step" ${canNext?'':'disabled'}>${state.stage===7?'完成探索':'下一步'} <span>→</span></button></div><button class="theory-link" id="step-principle">ⓘ 这一步为什么有效？</button></div>`;bindPanel();}
function enterStage(index,{scroll=false}={}){state.mode='guide';state.stage=index;state.guideDecision=null;state.comparison=null;if(index===4){state.offset=-32;}if(index===5){state.experiment=null;}if(index===6){newExperiment(state.targetPresent);}if(index===7){state.targetPresent=seed()%2===0;newExperiment(state.targetPresent).sample(24);state.running=true;}persist();render();if(scroll&&matchMedia('(max-width:620px)').matches)$('#control-panel').scrollIntoView({behavior:'smooth',block:'start'});}
function actGuide(){const i=state.stage;pulse();let message='';if(i===0){message='两路信号已制备：探测通路出发，参考通路留在本地。';markDone();}if(i===1){message=state.retention<.45?'参考损失较多。进入自由实验，可以比较它对判决的影响。':'参考信号已保留，等待回波返回后共同测量。';markDone();}if(i===2){message=state.targetPresent?'目标贡献进入回程；传播和反射损耗让回波变弱。':'已移走目标。加入环境噪声后，接收器仍会有读数。';markDone();}if(i===3){message='接收器收到了混合信号。仅凭杂乱读数还不能确定目标。';markDone();}if(i===4){if(Math.abs(state.offset)>8){toast('窗口尚未对齐。把滑块移到中间的“同步”附近。');return;}state.alignment=1;message='校准完成。对应模式已匹配，仍需联合测量与统计。';markDone();}if(i===5){if(!state.experiment)newExperiment(state.targetPresent);state.experiment.sample(1);markDone();message='获得一份随机读数。再往下，看看多次采样会发生什么。';}if(i===6){if(!state.experiment)newExperiment(state.targetPresent);const snap=state.experiment.getSnapshot();if(snap.samples>=96){toast('已达到本轮 96 次采样预算，可以继续判决环节。');return;}state.experiment.sample(8);if(state.experiment.getSnapshot().samples>=24)markDone();message=state.experiment.getSnapshot().samples>=24?'已积累至少 24 次观测。下一步试着判断一个隐藏目标。':'证据正在积累。新读数可能让它暂时转向另一侧。';}renderGuide();$('#action-status').textContent=message;syncLab();}
function bindPanel(){const main=$('#main-action');if(main)main.addEventListener('click',state.mode==='guide'?actGuide:state.mode==='sandbox'?compare:samplingChallenge);$('#next-step')?.addEventListener('click',()=>state.stage===7?showCompletion():enterStage(state.stage+1,{scroll:true}));$('#step-principle')?.addEventListener('click',()=>showPrinciple(state.stage));$$('[data-target]').forEach(b=>b.addEventListener('click',()=>{state.targetPresent=b.dataset.target==='true';renderGuide();syncLab();}));$('#retention')?.addEventListener('input',e=>{state.retention=+e.target.value/100;$('#retention-value').textContent=e.target.value+'%';settingsChanged();});$('#noise')?.addEventListener('input',e=>{state.noise=+e.target.value/100;$('#noise-value').textContent=e.target.value+'%';settingsChanged();});$('#alignment')?.addEventListener('input',e=>{state.offset=+e.target.value;$('#alignment-value').textContent=Math.abs(state.offset)<=5?'已对齐':state.offset<0?'偏早':'偏晚';syncLab();});$('#match')?.addEventListener('input',e=>{state.alignment=+e.target.value/100;$('#match-value').textContent=e.target.value+'%';settingsChanged();});$$('[data-guess]').forEach(b=>b.addEventListener('click',()=>state.mode==='challenge'?decideChallenge(b.dataset.guess==='true'):decideGuide(b.dataset.guess==='true')));$('#next-round')?.addEventListener('click',nextRound);$('#challenge-reset')?.addEventListener('click',()=>{startChallenge();render();});$('#sandbox-model')?.addEventListener('click',()=>openModal('sources'));$('#reset-defaults')?.addEventListener('click',()=>{state.noise=.6;state.retention=.95;state.alignment=1;state.comparison=null;render();toast('已恢复教学默认条件。');});}
function settingsChanged(){state.comparison=null;syncLab();if(state.mode==='sandbox'){const area=$('#comparison-result');if(area)area.innerHTML='<p class="compare-note">条件已改变，点击下方按钮重新试验。</p>';}}
function decideGuide(guess){if(state.guideDecision)return;state.guideDecision={guess,correct:guess===state.targetPresent};markDone();state.comparison=runComparison({...config(),trials:400,samples:24,seed:seed()});renderGuide();syncLab();}
function renderSandbox(){$('#control-panel').innerHTML=`<div class="chapter-kicker"><span>改变一个条件，观察一次变化</span><span class="chapter-number">自由实验</span></div><h2 class="chapter-title">条件变了，结果呢？</h2><p class="chapter-description sandbox-description">同样的采样预算，两种教学方案。试着增加噪声，或降低参考保存质量。</p><div class="control-area">${range('noise','背景噪声强度',Math.round(state.noise*100),'较弱','较强')}${range('retention','参考保留程度',Math.round(state.retention*100),'大量损失','充分保存')}${range('match','接收匹配程度',Math.round(state.alignment*100),'完全错配','充分匹配')}<div id="comparison-result">${state.comparison?comparisonHTML(state.comparison):'<p class="compare-note">每个条件各运行 400 次试验，观察统计表现。参数与结果均为教学模拟。</p>'}</div></div><div class="panel-actions"><button class="primary-button" id="main-action"><span>运行对照实验</span><span class="arrow">↗</span></button><button class="restart-link" id="reset-defaults">恢复默认条件</button><button class="theory-link" id="sandbox-model">ⓘ 怎样理解这些模拟数字？</button></div>`;bindPanel();}
function compare(){pulse();state.comparison=runComparison({...config(),trials:400,samples:24,seed:seed()});renderSandbox();const diff=state.comparison.quantum.accuracy-state.comparison.classical.accuracy;toast(diff>.005?'这组教学条件下，量子方案的正确率较高。试试降低参考保留程度。':diff<-.005?'这组教学条件下，量子方案没有显示优势。参考与接收条件很重要。':'这组试验结果接近。有限试验会波动，可以再运行一次。');}
function startChallenge(){state.challenge={round:1,correct:0,used:0,history:[],revealed:false,target:seed()%2===0,guess:null};state.mode='challenge';state.noise=.6;state.retention=.95;state.alignment=1;state.running=false;state.experiment=createExperiment({...config(),targetPresent:state.challenge.target,seed:seed()});}
function renderChallenge(){if(!state.challenge)startChallenge();const ch=state.challenge,s=state.experiment.getSnapshot(),done=ch.revealed;$('#control-panel').innerHTML=`<div class="chapter-kicker"><span>让证据带你接近答案</span><span class="chapter-number">挑战 ${ch.round} / 5</span></div><h2 class="chapter-title">现在，由你来判断。</h2><p class="chapter-description sandbox-description">目标真值已经隐藏。每批获得 8 个读数，你可以继续观察，也可以提交判断。</p><div class="challenge-score"><span>答对 ${ch.correct} 次</span><span>本轮预算 ${s.samples} / 96</span></div><div class="control-area">${evidence(s)}${done?`<div class="result-message ${ch.guess===ch.target?'':'incorrect'}">${ch.guess===ch.target?'✓ 判断正确':ch.guess?'这次发生了误报':'这次发生了漏检'}<br/>实际${ch.target?'存在':'不存在'}目标，本轮用了 ${s.samples} 个样本。${ch.guess!==ch.target?'有证据仍可能误判，这是统计探测的一部分。':''}</div>`:''}</div><div class="panel-actions">${done?`<button class="primary-button" id="next-round"><span>${ch.round===5?'查看挑战报告':'开始下一轮'}</span><span class="arrow">→</span></button>`:`<button class="primary-button" id="main-action" ${s.samples>=96?'disabled':''}><span>${s.samples>=96?'采样预算已用完':'采集 8 个样本'}</span><span class="arrow">↗</span></button><div class="decision-buttons"><button data-guess="true" ${s.samples?'':'disabled'}>◎ 有目标</button><button data-guess="false" ${s.samples?'':'disabled'}>○ 无目标</button></div>`}<p class="sampling-note">此挑战采用固定教学条件。单轮结果不能证明一种方案更优。</p><button class="restart-link" id="challenge-reset">重新开始五轮挑战</button></div>`;bindPanel();}
function samplingChallenge(){if(state.challenge.revealed)return;const n=state.experiment.getSnapshot().samples;if(n>=96)return;state.experiment.sample(Math.min(8,96-n));pulse();renderChallenge();}
function decideChallenge(guess){const ch=state.challenge,s=state.experiment.getSnapshot();if(ch.revealed||!s.samples)return;ch.guess=guess;ch.revealed=true;ch.correct+=+(guess===ch.target);ch.used+=s.samples;ch.history.push({target:ch.target,guess,samples:s.samples,llr:s.llr});renderChallenge();syncLab();}
function nextRound(){const ch=state.challenge;if(ch.round===5){showChallengeReport();return;}ch.round++;ch.target=seed()%2===0;ch.guess=null;ch.revealed=false;state.running=false;state.experiment=createExperiment({...config(),targetPresent:ch.target,seed:seed()});renderChallenge();syncLab();}
function render(){for(const b of $$('[data-mode]')){b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));}$('#bench-title').textContent=state.mode==='guide'?'量子照明实验台':state.mode==='sandbox'?'同条件对照实验':'隐藏目标探测台';if(state.mode==='guide')renderGuide();if(state.mode==='sandbox')renderSandbox();if(state.mode==='challenge')renderChallenge();renderTrack();syncLab();const messages={guide:['让每一次操作，都成为一次发现。','先理解信号如何旅行，再尝试在未知中做出判断。'],sandbox:['量子优势，需要合适的条件。','比较时固定其他条件，一次只改变一个参数。'],challenge:['一次判断有输赢，科学需要多次检验。','读数会波动。合理地收集证据，也是探测的一部分。']};$('#insight-title').textContent=messages[state.mode][0];$('#insight-copy').textContent=messages[state.mode][1];}
function setMode(mode){if(mode==='guide'){enterStage(state.stage);return;}if(mode==='challenge'&&!state.challenge)startChallenge();else state.mode=mode;if(mode==='sandbox'){state.running=true;state.comparison=null;state.alignment=1;}render();}

function modal(html){modalReturnFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#info-modal').showModal();$('#info-modal').scrollTop=0;}
function openModal(type){if(type==='notebook'){modal(`<h2>你的量子实验手册</h2><p>八个环节连起来，才构成一次完整探测。已经探索 ${state.completed.size} / 8 个环节，进度会保存在这台设备的浏览器中。</p><div class="notebook-list">${stages.map((s,i)=>`<details class="notebook-item"><summary>${state.completed.has(i)?'✓':'○'} ${String(i+1).padStart(2,'0')}　${s.title}</summary><p>${s.principle}</p><button class="secondary-button" data-jump="${i}">回到这个环节 →</button></details>`).join('')}</div><button class="restart-link" id="reset-progress">重新开始引导探索</button>`);$$('[data-jump]').forEach(b=>b.addEventListener('click',()=>{closeModal();enterStage(+b.dataset.jump,{scroll:true});}));$('#reset-progress').addEventListener('click',()=>{state.completed.clear();state.experiment=null;state.running=false;closeModal();enterStage(0);toast('引导探索已重置。');});return;}if(type==='science'){modal(`<h2>从量子关联，到探测证据。</h2><p>量子照明研究怎样在微弱回波与强背景中，利用初始纠缠的探测与参考模式，改善目标存在性判断。探测信号照射目标，参考留在本地，回波返回后参与适当的联合接收。</p><div class="note-box"><p>有意思的是：传播环境可以破坏纠缠，但在特定条件下，初始纠缠资源仍能带来检测优势。它来自整套制备、传播和接收过程。</p></div><h3>三个理解要点</h3><ul><li>保留的参考不能独自在本地给出远处目标的答案。</li><li>经典探测也会利用相关性；量子优势需要与合适的经典基准比较。</li><li>优势有适用条件，更多背景噪声仍会让绝对探测表现变差。</li></ul><p>依据：<a href="https://arxiv.org/abs/0810.0534" target="_blank" rel="noopener noreferrer">Tan 等（2008）</a>、<a href="https://arxiv.org/abs/0911.0950" target="_blank" rel="noopener noreferrer">Guha 与 Erkmen（2009）</a>。本作品围绕已设定区域的目标有无展开。</p><button class="secondary-button" id="more-model">阅读模型和文献 →</button>`);$('#more-model').addEventListener('click',()=>{closeModal();openModal('sources');});return;}modal(`<h2>科学依据与模型说明</h2><p>本作品为原创交互科普演示，装置与通路采用示意绘制。微波不可被人眼直接看见，动画中的光点表示信号运动，并非逐个可识别的光子。</p><div class="note-box"><p>${modelNote}</p></div><h3>数字从哪里来</h3><p>${modelDetails}</p><h3>关于联合接收</h3><p>实验台采用“保留参考—回波返回—两路联合处理—获得测量结果”的教学流程。具体微波实验可通过两模参量操作和光子数测量实现接收。本页高斯读数是统计抽象，并不复现该接收器的光子计数分布。</p><h3>进一步阅读</h3><ul class="source-list">${sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p>${s.note}</p></li>`).join('')}</ul><h3>作品与素材</h3><p>实验装置、动态路径、图标和界面均为本项目原创绘制，使用设备系统字体。没有复制论文插图。内容面向量子感知科普；正式参赛前可结合主办方要求进行专家审核与公开刊发。</p>`);}
function closeModal(){$('#info-modal').close();}
function showPrinciple(i){const s=stages[i];modal(`<div class="chapter-number">实验 ${String(i+1).padStart(2,'0')} / 08</div><h2>${s.title}</h2><p>${s.principle}</p><h3>把发现留在脑海里</h3><p>${s.question.prompt}</p><div class="quiz-options">${s.question.options.map((o,n)=>`<button class="quiz-option" data-answer="${n}">${String.fromCharCode(65+n)}　${o}</button>`).join('')}</div><p class="quiz-feedback" role="status" aria-live="polite"></p>`);$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>{const correct=+b.dataset.answer===s.question.correct;b.classList.add(correct?'correct':'wrong');$('.quiz-feedback').textContent=(correct?'理解正确。':'再想一想。')+s.question.explanation;if(correct)state.quizAnswers.add(i);}));}
function showCompletion(){const all=state.completed.size===8;modal(`<div class="completion-art">✳</div><div class="eyebrow">你的探索记录</div><h2>${all?'你已走完一束信号的旅程。':'这一轮探测完成了。'}</h2><p>已探索 ${state.completed.size} / 8 个环节。从制备纠缠信号，到保留参考、接收弱回波、联合测量，再到积累证据与判断，每一步都承担着不同的作用。</p><div class="note-box"><p>量子照明的关键：在合适条件下，利用初始量子资源与适当接收，让两种目标状态更容易被统计地区分。</p></div><div class="completion-actions"><button class="primary-button" id="go-challenge">开始独立探测 →</button><button class="secondary-button" id="save-card">保存探索卡</button></div>${all?'':`<button class="restart-link" id="continue-guide">继续尚未探索的环节</button>`}`);$('#go-challenge').addEventListener('click',()=>{closeModal();setMode('challenge');});$('#save-card').addEventListener('click',downloadCard);$('#continue-guide')?.addEventListener('click',()=>{closeModal();enterStage(stages.findIndex((_,i)=>!state.completed.has(i)));});}
function showChallengeReport(){const c=state.challenge;const errors=c.history.filter(r=>r.guess!==r.target);modal(`<div class="eyebrow">五轮挑战完成</div><h2>用证据，认识不确定性。</h2><div class="readout-row"><div class="readout"><span>正确判断</span><strong>${c.correct}<small> / 5</small></strong></div><div class="readout"><span>采样总数</span><strong>${c.used}</strong></div></div><p>误报 ${errors.filter(r=>r.guess).length} 次，漏检 ${errors.filter(r=>!r.guess).length} 次。有限样本下的判断可能出错；增加样本通常能改善平均表现，也需要更多资源。</p><table class="comparison-table"><thead><tr><th>轮次</th><th>真实状态</th><th>你的判断</th><th>样本数</th></tr></thead><tbody>${c.history.map((r,i)=>`<tr><td>${i+1}</td><td>${r.target?'有目标':'无目标'}</td><td>${r.guess?'有目标':'无目标'}</td><td>${r.samples}</td></tr>`).join('')}</tbody></table><p>这五轮是个人体验记录。方法之间的性能比较，请在自由实验中查看相同条件下的批量结果。</p><div class="completion-actions"><button class="primary-button" id="again-challenge">再挑战一次 →</button><button class="secondary-button" id="go-sandbox">探索影响条件</button></div>`);$('#again-challenge').addEventListener('click',()=>{closeModal();startChallenge();render();});$('#go-sandbox').addEventListener('click',()=>{closeModal();setMode('sandbox');});}
function downloadCard(){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="1080" viewBox="0 0 800 1080"><rect width="800" height="1080" fill="#f5f5ee"/><rect x="35" y="35" width="730" height="1010" rx="30" fill="none" stroke="#c9d7b6"/><circle cx="400" cy="275" r="125" fill="#244d3c"/><circle cx="400" cy="275" r="80" fill="none" stroke="#d3ed83" stroke-width="2"/><ellipse cx="400" cy="275" rx="110" ry="40" fill="none" stroke="#d3ed83" stroke-width="2" transform="rotate(-35 400 275)"/><circle cx="400" cy="275" r="13" fill="#d3ed83"/><g font-family="Microsoft YaHei,PingFang SC,sans-serif" text-anchor="middle" fill="#244d3c"><text x="400" y="100" font-size="22" letter-spacing="6">量子回声 · 探索记录</text><text x="400" y="475" font-size="39">我走过了一束信号的旅程</text><text x="400" y="545" font-size="23">已探索 ${state.completed.size} / 8 个环节</text><text x="400" y="650" font-size="22">制备信号 · 保存参考 · 发射探测</text><text x="400" y="695" font-size="22">接收噪声 · 匹配校准 · 联合测量</text><text x="400" y="740" font-size="22">积累证据 · 判决验证</text><text x="400" y="860" font-size="19">在噪声之中，听见量子回声。</text><text x="400" y="965" font-size="14" fill="#869578">解读量子世界 · 洞见科技未来 / 教学模拟</text></g></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='量子回声-探索卡.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('探索卡已生成，记录属于你的发现。');}

document.addEventListener('click',e=>{const mode=e.target.closest('[data-mode]');if(mode)setMode(mode.dataset.mode);const step=e.target.closest('[data-stage]');if(step)enterStage(+step.dataset.stage);const m=e.target.closest('[data-modal]');if(m)openModal(m.dataset.modal);});
$('#lab').addEventListener('device-select',e=>{if(state.mode==='guide')enterStage(e.detail.stage);else showPrinciple(e.detail.stage);});
$('#motion-toggle').addEventListener('click',()=>{state.paused=!state.paused;syncLab();});
$('#close-modal').addEventListener('click',closeModal);
$('#info-modal').addEventListener('click',e=>{if(e.target===$('#info-modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#info-modal').addEventListener('close',()=>{if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});});
window.addEventListener('pagehide',persist);
if(state.stage===7){state.targetPresent=seed()%2===0;newExperiment(state.targetPresent).sample(24);}render();
